coachView.changeJsFunction:
// Get the markdown container element
var markdownContainer = this.context.element.querySelector(".markdown-content");

// Get the updated markdown text data
var markdownText = this.getData() || "";

// Get configuration options
var enableSanitization = this.getOption("enableSanitization") !== false; // Default true
var showLineNumbers = this.getOption("showLineNumbers") || false;
var theme = this.getOption("theme") || "default"; // default, dark, light

// Apply theme class
var container = this.context.element.querySelector(".markdown-viewer-container");
container.className = "markdown-viewer-container markdown-theme-" + theme;

// Simple markdown parser function
function parseMarkdown(text) {
  if (!text) return "";

  var html = text;

  // Escape HTML if sanitization is enabled
  if (enableSanitization) {
    var ampRegex = /&/g;
    var ltRegex = /</g;
    var gtRegex = />/g;
    var quotRegex = /"/g;
    var aposRegex = /'/g;

    html = html
      .replace(ampRegex, String.fromCharCode(38) + "amp;")
      .replace(ltRegex, String.fromCharCode(38) + "lt;")
      .replace(gtRegex, String.fromCharCode(38) + "gt;")
      .replace(quotRegex, String.fromCharCode(38) + "quot;")
      .replace(aposRegex, String.fromCharCode(38) + "#039;");
  }

  // Headers (h1-h6)
  html = html.replace(/^######\s+(.+)$/gm, '<h6>$1</h6>');
  html = html.replace(/^#####\s+(.+)$/gm, '<h5>$1</h5>');
  html = html.replace(/^####\s+(.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^###\s+(.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^##\s+(.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^#\s+(.+)$/gm, '<h1>$1</h1>');

  // Horizontal rules
  html = html.replace(/^---$/gm, '<hr>');
  html = html.replace(/^\*\*\*$/gm, '<hr>');
  html = html.replace(/^___$/gm, '<hr>');

  // Code blocks (fenced with ```)
  html = html.replace(/```(\w+)?\n([\s\S]*?)```/g, function(match, lang, code) {
    var langClass = lang ? ' class="language-' + lang + '"' : '';
    return '<pre><code' + langClass + '>' + code.trim() + '</code></pre>';
  });

  // Inline code
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Bold
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/__([^_]+)__/g, '<strong>$1</strong>');

  // Italic
  html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  html = html.replace(/_([^_]+)_/g, '<em>$1</em>');

  // Strikethrough
  html = html.replace(/~~([^~]+)~~/g, '<del>$1</del>');

  // Links
  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');

  // Images
  html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" loading="lazy">');

  // Blockquotes
  html = html.replace(/^>\s+(.+)$/gm, '<blockquote>$1</blockquote>');

  // Unordered lists
  html = html.replace(/^\*\s+(.+)$/gm, '<li>$1</li>');
  html = html.replace(/^-\s+(.+)$/gm, '<li>$1</li>');
  html = html.replace(/^(\+)\s+(.+)$/gm, '<li>$2</li>');

  // Ordered lists
  html = html.replace(/^\d+\.\s+(.+)$/gm, '<li>$1</li>');

  // Wrap consecutive list items in ul/ol tags
  html = html.replace(/(<li>.*<\/li>\n?)+/g, function(match) {
    return '<ul>' + match + '</ul>';
  });

  // Tables
  html = html.replace(/\|(.+)\|\n\|[-:\s|]+\|\n((?:\|.+\|\n?)+)/g, function(match, header, rows) {
    var headerCells = header.split('|').filter(function(cell) { return cell.trim(); });
    var headerHtml = '<thead><tr>' + headerCells.map(function(cell) {
      return '<th>' + cell.trim() + '</th>';
    }).join('') + '</tr></thead>';

    var rowsHtml = rows.trim().split('\n').map(function(row) {
      var cells = row.split('|').filter(function(cell) { return cell.trim(); });
      return '<tr>' + cells.map(function(cell) {
        return '<td>' + cell.trim() + '</td>';
      }).join('') + '</tr>';
    }).join('');

    return '<table><tbody>' + headerHtml + rowsHtml + '</tbody></table>';
  });

  // Paragraphs (wrap text not already in tags)
  html = html.replace(/^(?!<[^>]+>)(.+)$/gm, function(match) {
    if (match.trim() === '') return '';
    if (match.match(/^<(h[1-6]|hr|pre|blockquote|ul|ol|table)/)) return match;
    return '<p>' + match + '</p>';
  });

  // Clean up extra newlines
  html = html.replace(/\n\n+/g, '\n');

  return html;
}

// Parse and render the markdown
var renderedHtml = parseMarkdown(markdownText);

// Add line numbers if enabled
if (showLineNumbers) {
  var lines = renderedHtml.split('\n');
  renderedHtml = '<div class="markdown-with-lines">' +
    lines.map(function(line, index) {
      return '<div class="markdown-line"><span class="line-number">' + (index + 1) + '</span>' +
        '<span class="line-content">' + line + '</span></div>';
    }).join('') +
    '</div>';
}

// Set the rendered HTML
markdownContainer.innerHTML = renderedHtml;

// Trigger custom event for content change
this.executeEventHandlingFunction(this, "onContentChange", {
  originalText: markdownText,
  renderedHtml: renderedHtml
});

// Made with Bob

inlineScript.scriptBlock:
// Get the markdown container element
var markdownContainer = this.context.element.querySelector(".markdown-content");

// Get the markdown text data
var markdownText = this.getData() || "";

// Get configuration options
var enableSanitization = this.getOption("enableSanitization") !== false; // Default true
var showLineNumbers = this.getOption("showLineNumbers") || false;
var theme = this.getOption("theme") || "default"; // default, dark, light

// Apply theme class
var container = this.context.element.querySelector(".markdown-viewer-container");
container.className = "markdown-viewer-container markdown-theme-" + theme;

// Simple markdown parser function
function parseMarkdown(text) {
  if (!text) return "";

  var html = text;

  // Escape HTML if sanitization is enabled
  if (enableSanitization) {
    var ampRegex = /&/g;
    var ltRegex = /</g;
    var gtRegex = />/g;
    var quotRegex = /"/g;
    var aposRegex = /'/g;

    html = html
      .replace(ampRegex, String.fromCharCode(38) + "amp;")
      .replace(ltRegex, String.fromCharCode(38) + "lt;")
      .replace(gtRegex, String.fromCharCode(38) + "gt;")
      .replace(quotRegex, String.fromCharCode(38) + "quot;")
      .replace(aposRegex, String.fromCharCode(38) + "#039;");
  }

  // Headers (h1-h6)
  html = html.replace(/^######\s+(.+)$/gm, '<h6>$1</h6>');
  html = html.replace(/^#####\s+(.+)$/gm, '<h5>$1</h5>');
  html = html.replace(/^####\s+(.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^###\s+(.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^##\s+(.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^#\s+(.+)$/gm, '<h1>$1</h1>');

  // Horizontal rules
  html = html.replace(/^---$/gm, '<hr>');
  html = html.replace(/^\*\*\*$/gm, '<hr>');
  html = html.replace(/^___$/gm, '<hr>');

  // Code blocks (fenced with ```)
  html = html.replace(/```(\w+)?\n([\s\S]*?)```/g, function(match, lang, code) {
    var langClass = lang ? ' class="language-' + lang + '"' : '';
    return '<pre><code' + langClass + '>' + code.trim() + '</code></pre>';
  });

  // Inline code
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Bold
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/__([^_]+)__/g, '<strong>$1</strong>');

  // Italic
  html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  html = html.replace(/_([^_]+)_/g, '<em>$1</em>');

  // Strikethrough
  html = html.replace(/~~([^~]+)~~/g, '<del>$1</del>');

  // Links
  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');

  // Images
  html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" loading="lazy">');

  // Blockquotes
  html = html.replace(/^>\s+(.+)$/gm, '<blockquote>$1</blockquote>');

  // Unordered lists
  html = html.replace(/^\*\s+(.+)$/gm, '<li>$1</li>');
  html = html.replace(/^-\s+(.+)$/gm, '<li>$1</li>');
  html = html.replace(/^(\+)\s+(.+)$/gm, '<li>$2</li>');

  // Ordered lists
  html = html.replace(/^\d+\.\s+(.+)$/gm, '<li>$1</li>');

  // Wrap consecutive list items in ul/ol tags
  html = html.replace(/(<li>.*<\/li>\n?)+/g, function(match) {
    // Check if it's an ordered list (starts with number)
    if (/^\d+\./.test(text.match(new RegExp(match.replace(/<[^>]+>/g, ''))))) {
      return '<ol>' + match + '</ol>';
    }
    return '<ul>' + match + '</ul>';
  });

  // Tables
  html = html.replace(/\|(.+)\|\n\|[-:\s|]+\|\n((?:\|.+\|\n?)+)/g, function(match, header, rows) {
    var headerCells = header.split('|').filter(function(cell) { return cell.trim(); });
    var headerHtml = '<thead><tr>' + headerCells.map(function(cell) {
      return '<th>' + cell.trim() + '</th>';
    }).join('') + '</tr></thead>';

    var rowsHtml = rows.trim().split('\n').map(function(row) {
      var cells = row.split('|').filter(function(cell) { return cell.trim(); });
      return '<tr>' + cells.map(function(cell) {
        return '<td>' + cell.trim() + '</td>';
      }).join('') + '</tr>';
    }).join('');

    return '<table><tbody>' + headerHtml + rowsHtml + '</tbody></table>';
  });

  // Paragraphs (wrap text not already in tags)
  html = html.replace(/^(?!<[^>]+>)(.+)$/gm, function(match) {
    if (match.trim() === '') return '';
    if (match.match(/^<(h[1-6]|hr|pre|blockquote|ul|ol|table)/)) return match;
    return '<p>' + match + '</p>';
  });

  // Clean up extra newlines
  html = html.replace(/\n\n+/g, '\n');

  return html;
}

// Parse and render the markdown
var renderedHtml = parseMarkdown(markdownText);

// Add line numbers if enabled
if (showLineNumbers) {
  var lines = renderedHtml.split('\n');
  renderedHtml = '<div class="markdown-with-lines">' +
    lines.map(function(line, index) {
      return '<div class="markdown-line"><span class="line-number">' + (index + 1) + '</span>' +
        '<span class="line-content">' + line + '</span></div>';
    }).join('') +
    '</div>';
}

// Set the rendered HTML
markdownContainer.innerHTML = renderedHtml;

// Register event handling function for content changes
this.registerEventHandlingFunction = function(context, eventName, args) {
  if (eventName === "onContentChange") {
    // Trigger custom event when markdown content changes
    var event = new CustomEvent("markdownContentChanged", {
      detail: {
        originalText: markdownText,
        renderedHtml: renderedHtml
      }
    });
    context.element.dispatchEvent(event);
  }
};

// Made with Bob

/* Markdown Viewer Widget Styles */

.markdown-viewer-container {
  width: 100%;
  min-height: 50px;
  padding: 16px;
  background-color: var(--markdown-bg, #ffffff);
  color: var(--markdown-text, #161616);
  font-family: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 14px;
  line-height: 1.6;
  overflow-wrap: break-word;
  word-wrap: break-word;
}

.markdown-content {
  max-width: 100%;
}

/* Theme: Default */
.markdown-theme-default {
  --markdown-bg: #ffffff;
  --markdown-text: #161616;
  --markdown-heading: #161616;
  --markdown-link: #0f62fe;
  --markdown-link-hover: #0043ce;
  --markdown-code-bg: #f4f4f4;
  --markdown-code-text: #c6c6c6;
  --markdown-border: #e0e0e0;
  --markdown-blockquote-bg: #f4f4f4;
  --markdown-blockquote-border: #0f62fe;
}

/* Theme: Light */
.markdown-theme-light {
  --markdown-bg: #f4f4f4;
  --markdown-text: #161616;
  --markdown-heading: #161616;
  --markdown-link: #0f62fe;
  --markdown-link-hover: #0043ce;
  --markdown-code-bg: #e0e0e0;
  --markdown-code-text: #525252;
  --markdown-border: #c6c6c6;
  --markdown-blockquote-bg: #ffffff;
  --markdown-blockquote-border: #0f62fe;
}

/* Theme: Dark */
.markdown-theme-dark {
  --markdown-bg: #161616;
  --markdown-text: #f4f4f4;
  --markdown-heading: #ffffff;
  --markdown-link: #78a9ff;
  --markdown-link-hover: #a6c8ff;
  --markdown-code-bg: #262626;
  --markdown-code-text: #c6c6c6;
  --markdown-border: #393939;
  --markdown-blockquote-bg: #262626;
  --markdown-blockquote-border: #78a9ff;
}

/* Headers */
.markdown-content h1,
.markdown-content h2,
.markdown-content h3,
.markdown-content h4,
.markdown-content h5,
.markdown-content h6 {
  color: var(--markdown-heading);
  font-weight: 600;
  margin-top: 24px;
  margin-bottom: 16px;
  line-height: 1.25;
}

.markdown-content h1 {
  font-size: 32px;
  border-bottom: 1px solid var(--markdown-border);
  padding-bottom: 8px;
}

.markdown-content h2 {
  font-size: 24px;
  border-bottom: 1px solid var(--markdown-border);
  padding-bottom: 8px;
}

.markdown-content h3 {
  font-size: 20px;
}

.markdown-content h4 {
  font-size: 16px;
}

.markdown-content h5 {
  font-size: 14px;
}

.markdown-content h6 {
  font-size: 12px;
  color: #6f6f6f;
}

/* Paragraphs */
.markdown-content p {
  margin-top: 0;
  margin-bottom: 16px;
}

/* Links */
.markdown-content a {
  color: var(--markdown-link);
  text-decoration: none;
  transition: color 110ms cubic-bezier(0.2, 0, 0.38, 0.9);
}

.markdown-content a:hover {
  color: var(--markdown-link-hover);
  text-decoration: underline;
}

.markdown-content a:focus {
  outline: 2px solid var(--markdown-link);
  outline-offset: 2px;
}

/* Code */
.markdown-content code {
  background-color: var(--markdown-code-bg);
  color: var(--markdown-code-text);
  padding: 2px 6px;
  border-radius: 3px;
  font-family: 'IBM Plex Mono', 'Menlo', 'DejaVu Sans Mono', 'Bitstream Vera Sans Mono', Courier, monospace;
  font-size: 85%;
}

.markdown-content pre {
  background-color: var(--markdown-code-bg);
  border: 1px solid var(--markdown-border);
  border-radius: 4px;
  padding: 16px;
  overflow-x: auto;
  margin-bottom: 16px;
}

.markdown-content pre code {
  background-color: transparent;
  padding: 0;
  border-radius: 0;
  font-size: 12px;
  line-height: 1.5;
}

/* Lists */
.markdown-content ul,
.markdown-content ol {
  margin-top: 0;
  margin-bottom: 16px;
  padding-left: 32px;
}

.markdown-content li {
  margin-bottom: 4px;
}

.markdown-content ul ul,
.markdown-content ul ol,
.markdown-content ol ul,
.markdown-content ol ol {
  margin-top: 4px;
  margin-bottom: 4px;
}

/* Blockquotes */
.markdown-content blockquote {
  background-color: var(--markdown-blockquote-bg);
  border-left: 4px solid var(--markdown-blockquote-border);
  padding: 8px 16px;
  margin: 0 0 16px 0;
  color: var(--markdown-text);
}

.markdown-content blockquote p {
  margin-bottom: 0;
}

/* Horizontal Rules */
.markdown-content hr {
  border: 0;
  border-top: 1px solid var(--markdown-border);
  margin: 24px 0;
}

/* Images */
.markdown-content img {
  max-width: 100%;
  height: auto;
  border-radius: 4px;
  margin: 8px 0;
}

/* Tables */
.markdown-content table {
  border-collapse: collapse;
  width: 100%;
  margin-bottom: 16px;
  overflow-x: auto;
  display: block;
}

.markdown-content table thead {
  background-color: var(--markdown-code-bg);
}

.markdown-content table th,
.markdown-content table td {
  border: 1px solid var(--markdown-border);
  padding: 8px 12px;
  text-align: left;
}

.markdown-content table th {
  font-weight: 600;
}

.markdown-content table tr:nth-child(even) {
  background-color: var(--markdown-code-bg);
}

/* Text Formatting */
.markdown-content strong {
  font-weight: 600;
}

.markdown-content em {
  font-style: italic;
}

.markdown-content del {
  text-decoration: line-through;
  opacity: 0.7;
}

/* Line Numbers (optional feature) */
.markdown-with-lines {
  display: table;
  width: 100%;
}

.markdown-line {
  display: table-row;
}

.line-number {
  display: table-cell;
  text-align: right;
  padding-right: 16px;
  color: #8d8d8d;
  user-select: none;
  width: 40px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 12px;
}

.line-content {
  display: table-cell;
  padding-left: 8px;
}

/* Accessibility */
.markdown-viewer-container:focus {
  outline: 2px solid var(--markdown-link);
  outline-offset: 2px;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .markdown-viewer-container {
    padding: 12px;
  }

  .markdown-content h1 {
    font-size: 28px;
  }

  .markdown-content h2 {
    font-size: 22px;
  }

  .markdown-content h3 {
    font-size: 18px;
  }

  .markdown-content pre {
    padding: 12px;
  }
}

/* Made with Bob */
